using System.Reflection;

Assembly assembly = Assembly.GetExecutingAssembly();

Console.WriteLine($"Name: {assembly.GetName().Name}");
Console.WriteLine($"Version: {assembly.GetName().Version}");

// List all public types
foreach (Type type in assembly.GetExportedTypes())
{
    Console.WriteLine($"  {type.FullName}");
}

// Read a custom attribute from the assembly
var attr = assembly.GetCustomAttribute<AssemblyTitleAttribute>();
Console.WriteLine($"Title: {attr?.Title}");

using System.Reflection;

// Load by full display name (name, version, culture, public key token)
Assembly plugin = Assembly.Load(
    "MyPlugin, Version=1.0.0.0, Culture=neutral, PublicKeyToken=abc123");

// Enumerate types in the loaded assembly
foreach (Type type in plugin.GetTypes())
{
    if (typeof(IPlugin).IsAssignableFrom(type) && !type.IsAbstract)
    {
        IPlugin instance = (IPlugin)Activator.CreateInstance(type);
        instance.Run();
    }
}
